    static byte[] bytes(Message message){return message.getContent().toByteArray();}
    static RaftClientReply reply(UUID group,String peer,byte[] bytes){return RaftClientReply.newBuilder().setClientId(ClientId.randomId()).setServerId(RaftPeerId.valueOf(peer)).setGroupId(RaftGroupId.valueOf(group)).setCallId(0).setSuccess().setMessage(Message.valueOf(ByteString.copyFrom(bytes))).build();}
    @Test void coldCapturingFailureUsesOneSuccessorThroughNativeRegistrationTransferAndJournalRetry()throws Exception{
        try(var f=new Workflow()){
            f.loseConfiguration=false;var journal=Files.createDirectory(root.resolve("successor-journal"));var a=RatisNodeRuntime.sourceRequest(f.source.definition,f.catalogueId,f.source.receiver);var once=new java.util.concurrent.atomic.AtomicBoolean(true);f.artifacts.captureForceObserver(path->{if(once.getAndSet(false))throw new IOException("Forced CAPTURING acknowledgement lost before image");});
            RatisRelocationController.Anchors anchors=receiver->{var owner=new ReplicaDescriptor(receiver.nodeId(),receiver.nodeIncarnation(),receiver.replicaId(),receiver.peerId(),receiver.address(),ReplicaDescriptor.Role.VOTER);return new RatisRelocationController.Anchor(new RangeDescriptor(f.catalogueId,f.catalogueId,1,0,null,null,RangeDescriptor.TopologyState.ACTIVE,List.of(owner)),owner);};
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,anchors)){var handle=controller.prepare(f.source.definition);assertThrows(IOException.class,()->controller.advance(handle,64));assertEquals(RatisRelocationController.Phase.REGISTER,handle.phase());assertNull(f.registration);assertEquals(0,f.source.store.activeSnapshotPins());assertEquals(RatisTopologySourceSnapshotArtifacts.PublicationPhase.CAPTURING,f.artifacts.publicationPhase(a));}
            f.source.store.applyNoop(new ApplyPosition(1,f.source.store.applied().index()+1));f.restartSource();UUID b;
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,anchors)){var handle=controller.reopen(f.source.definition.intentId());assertEquals(RatisRelocationController.Phase.TRANSFER,controller.advance(handle,1));b=f.registration.sourceTransferId();assertNotEquals(a.transferId(),b);assertEquals(b,f.artifacts.abandoned(a).successorId());assertEquals(b,NativeTopologyLearnerRegistration.decode(f.registration.encode()).sourceTransferId());assertFalse(f.receiver.topologyLearnerImageInstalled());var fields=RatisSchemaClientJournal.read(journal.resolve(handle.intentId()+".relocation"));assertEquals(b,RatisTopologySourceSnapshotRpc.request(fields.get("sourceRequest")).transferId());}
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,receiver->{throw new AssertionError("Chosen native registration must be replayed");})){var handle=controller.reopen(f.source.definition.intentId());assertEquals(RatisRelocationController.Phase.ACTIVE,controller.advance(handle,64));assertEquals(b,f.receiver.topologyLearnerRegistration().sourceTransferId());assertTrue(f.receiver.topologyLearnerImageInstalled());assertEquals(0,f.source.store.activeSnapshotPins());assertEquals(0,f.artifacts.reservedImageBytes());assertEquals(b,f.artifacts.abandoned(a).successorId());assertArrayEquals(f.source.definition.targetDirectory().payloadDigest(),RangeDirectoryCodec.decode(f.read(f.domainKey())).payloadDigest());}
        }
    }
    @Test void listenerImageTailAndPromotionPublishOnlyAfterNativeReadinessWithExactLostCasRecovery()throws Exception {
        try(var f=new Workflow()){
            var journal=Files.createDirectories(root.resolve("controller"));UUID id=f.source.definition.intentId();try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,r->{var anchor=new ReplicaDescriptor(r.nodeId(),r.nodeIncarnation(),r.replicaId(),r.peerId(),r.address(),ReplicaDescriptor.Role.VOTER);return new RatisRelocationController.Anchor(new RangeDescriptor(f.catalogueId,f.catalogueId,1,0,null,null,RangeDescriptor.TopologyState.ACTIVE,List.of(anchor)),anchor);})){var handle=controller.prepare(f.source.definition);assertThrows(IOException.class,()->controller.advance(handle,64));assertEquals(RatisRelocationController.Phase.CONFIGURE,handle.phase());assertEquals(1,f.adminCalls);assertTrue(f.receiver.topologyLearnerImageInstalled());assertFalse(f.receiver.admissionOpen());assertArrayEquals(f.source.definition.sourceDirectory().payloadDigest(),RangeDirectoryCodec.decode(f.read(f.domainKey())).payloadDigest());}
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,r->{throw new AssertionError("Known receiver must not recapture");})){var handle=controller.reopen(id);assertEquals(RatisRelocationController.Phase.ACTIVE,controller.advance(handle,64));assertEquals(1,f.adminCalls,"Already committed target must resolve unknown CAS without another mutation");assertFalse(f.receiver.admissionOpen());assertEquals(0,f.source.store.activeSnapshotPins());assertArrayEquals(f.source.definition.targetDirectory().payloadDigest(),RangeDirectoryCodec.decode(f.read(f.domainKey())).payloadDigest());}
            var previous=f.source.definition.targetDirectory();var range=previous.ranges().getFirst();var voter=new ReplicaDescriptor(f.source.receiver.nodeId(),f.source.receiver.nodeIncarnation(),f.source.receiver.replicaId(),f.source.receiver.peerId(),f.source.receiver.address(),ReplicaDescriptor.Role.VOTER);var promoted=new RangeDescriptor(range.rangeId(),range.groupId(),range.rangeEpoch(),range.configurationVersion()+1,null,null,range.topologyState(),List.of(f.source.donor,voter));var next=new RangeDirectory(previous.clusterId(),previous.databaseId(),previous.domainId(),previous.schemaEpoch(),previous.schemaDigest(),previous.generation()+1,previous.columns(),previous.routingPrefixBytes(),List.of(promoted));var definition=new TopologyChange.Definition(new UUID(200,30),previous,next);
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,r->{throw new AssertionError("Promotion must preserve original registered image");})){var handle=controller.prepare(definition);assertEquals(RatisRelocationController.Phase.ACTIVE,controller.advance(handle,64));assertEquals(2,f.adminCalls);assertTrue(f.receiver.admissionOpen());assertNull(f.receiver.topologyBirth());assertNull(f.receiver.topologyActivation());assertArrayEquals(f.registration.encode(),f.receiver.topologyLearnerRegistration().encode());assertArrayEquals(next.payloadDigest(),RangeDirectoryCodec.decode(f.read(f.domainKey())).payloadDigest());}
        }
    }
    @Test void behindSchemaPromotionRecoversExactLaterImageAfterUnknownPreparationWithoutChangingOriginalRegistration()throws Exception{
        try(var f=new Workflow(5)){
            f.loseConfiguration=false;var journal=Files.createDirectories(root.resolve("recovery-controller"));
            RatisRelocationController.Anchors anchors=r->{var anchor=new ReplicaDescriptor(r.nodeId(),r.nodeIncarnation(),r.replicaId(),r.peerId(),r.address(),ReplicaDescriptor.Role.VOTER);return new RatisRelocationController.Anchor(new RangeDescriptor(f.catalogueId,f.catalogueId,1,0,null,null,RangeDescriptor.TopologyState.ACTIVE,List.of(anchor)),anchor);};
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,anchors)){assertEquals(RatisRelocationController.Phase.ACTIVE,controller.advance(controller.prepare(f.source.definition),64));}
            var original=f.registration.encode();var initialCut=f.registration.imageCut();var directory=f.evolveSource(f.source.definition.targetDirectory());assertArrayEquals(f.source.schema.digest(),f.receiver.schemaDigest());var range=directory.ranges().getFirst();var voter=new ReplicaDescriptor(f.source.receiver.nodeId(),f.source.receiver.nodeIncarnation(),f.source.receiver.replicaId(),f.source.receiver.peerId(),f.source.receiver.address(),ReplicaDescriptor.Role.VOTER);var replacement=new ArrayList<>(range.replicas());replacement.removeIf(r->r.replicaId().equals(f.source.receiver.replicaId()) || r.peerId().equals("donor4"));replacement.add(voter);assertEquals(5,replacement.size());var targetRange=new RangeDescriptor(range.rangeId(),range.groupId(),range.rangeEpoch(),range.configurationVersion()+1,range.lowerInclusive(),range.upperExclusive(),range.topologyState(),replacement);var target=new RangeDirectory(directory.clusterId(),directory.databaseId(),directory.domainId(),directory.schemaEpoch(),directory.schemaDigest(),directory.generation()+1,directory.columns(),directory.routingPrefixBytes(),List.of(targetRange));var promotion=new TopologyChange.Definition(new UUID(200,44),directory,target);f.loseRecovery=true;
            try(var controller=new RatisRelocationController(journal,directory.clusterId(),directory.databaseId(),f.binding,f.control,f.data,r->{throw new AssertionError("Existing registration must not use bootstrap");})){var handle=controller.prepare(promotion);var unknown=assertThrows(IOException.class,()->controller.advance(handle,64));assertEquals("Lost forced recovery preparation reply",unknown.getMessage());assertEquals(RatisRelocationController.Phase.REGISTER,handle.phase());assertEquals(1,f.recoveryCalls,"Must reach receiver109");assertEquals(2,f.source.captures.get(),"Bootstrap plus later recovery image");assertEquals(1,f.source.store.activeSnapshotPins(),"Unknown109 retains original recovery pin");assertFalse(f.receiver.admissionOpen());assertNotNull(f.receiver.topologyLearnerImagePermission());}
            try(var controller=new RatisRelocationController(journal,directory.clusterId(),directory.databaseId(),f.binding,f.control,f.data,r->{throw new AssertionError();})){var handle=controller.reopen(promotion.intentId());assertEquals(RatisRelocationController.Phase.ACTIVE,controller.advance(handle,64));assertEquals(2,f.recoveryCalls);assertEquals(2,f.source.captures.get(),"Unknown109 must reuse the original qualified image");assertTrue(f.receiver.topologyLearnerImageInstalled(f.recoveryPrepared.image().position(),f.recoveryPrepared.image().sha256()));assertTrue(f.receiver.admissionOpen());assertArrayEquals(original,f.receiver.topologyLearnerRegistration().encode());assertEquals(initialCut,f.receiver.topologyLearnerRegistration().imageCut());assertArrayEquals(target.schemaDigest(),f.receiver.schemaDigest());assertArrayEquals(target.payloadDigest(),RangeDirectoryCodec.decode(f.read(f.domainKey())).payloadDigest());assertEquals(0,f.source.store.activeSnapshotPins());}
        }
    }
    @Test void retainedJournalBoundSurvivesRestartAndFailedCheckpointCannotDispatch()throws Exception {
        try(var f=new Workflow()){
            var journal=Files.createDirectories(root.resolve("bounded-controller"));
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,r->{throw new AssertionError();})){
                var handle=controller.prepare(f.source.definition);var originalCut=f.catalogue.applied();var hidden=root.resolve("hidden-controller");Files.move(journal,hidden);
                try{assertThrows(IOException.class,()->controller.advance(handle,1));assertThrows(IOException.class,()->controller.advance(handle,1));assertEquals(originalCut,f.catalogue.applied(),"Unforced in-memory proposal must never be dispatched");}finally{Files.move(hidden,journal);}
                controller.advance(handle,2);assertNotEquals(originalCut,f.catalogue.applied());
                for(int i=1;i<8;i++)controller.prepare(new TopologyChange.Definition(new UUID(201,i),f.source.definition.sourceDirectory(),f.source.definition.targetDirectory()));
            }
            try(var controller=new RatisRelocationController(journal,f.source.schema.clusterId(),f.source.schema.databaseId(),f.binding,f.control,f.data,r->{throw new AssertionError();})){
                assertThrows(IOException.class,()->controller.prepare(new TopologyChange.Definition(new UUID(201,9),f.source.definition.sourceDirectory(),f.source.definition.targetDirectory())));
                for(int i=1;i<8;i++)assertEquals(RatisRelocationController.Phase.DEFINITION,controller.reopen(new UUID(201,i)).phase());
            }
        }
    }

